import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { billingLogic } from 'lib/logic/billing/billingLogic'
import { copyToClipboard } from 'lib/utils/copyToClipboard'
import { eventUsageLogic } from 'lib/utils/eventUsageLogic'

import { healthSummaryLogic } from './healthSummaryLogic'

export type HelpBadgeStatus = 'danger' | 'warning' | 'success'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicValues {
    accountOwner: { name?: string; email?: string } | null // billingLogic
    criticalCount: number // healthSummaryLogic
    unsnoozedCount: number // healthSummaryLogic
    warningCount: number // healthSummaryLogic
    hasHealthIssue: boolean
    isHelpMenuOpen: boolean
    triggerBadgeContent: string
    triggerBadgeStatus: HelpBadgeStatus
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicActions {
    reportAccountOwnerClicked: ({ name, email }: { name: string; email: string }) => {
        name: string
        email: string
    } // eventUsageLogic
    copyAccountOwnerEmail: () => {
        value: true
    }
    setHelpMenuOpen: (isOpen: boolean) => {
        isOpen: boolean
    }
    toggleHelpMenu: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface helpMenuLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasHealthIssue: (unsnoozedCount: number) => boolean
        triggerBadgeContent: (hasHealthIssue: boolean) => string
        triggerBadgeStatus: (hasHealthIssue: boolean, criticalCount: number, warningCount: number) => HelpBadgeStatus
    }
}

export type helpMenuLogicType = MakeLogicType<
    helpMenuLogicValues,
    helpMenuLogicActions,
    Record<string, any>,
    helpMenuLogicMeta
>

export const helpMenuLogic = kea<helpMenuLogicType>([
    path(['lib', 'components', 'HelpMenu', 'helpMenuLogic']),
    connect(() => ({
        values: [
            billingLogic,
            ['accountOwner'],
            healthSummaryLogic,
            ['unsnoozedCount', 'criticalCount', 'warningCount'],
        ],
        actions: [eventUsageLogic, ['reportAccountOwnerClicked']],
    })),
    actions({
        setHelpMenuOpen: (isOpen: boolean) => ({ isOpen }),
        toggleHelpMenu: true,
        copyAccountOwnerEmail: true,
    }),
    reducers({
        isHelpMenuOpen: [
            false,
            {
                setHelpMenuOpen: (_, { isOpen }) => isOpen,
                toggleHelpMenu: (state) => !state,
            },
        ],
    }),
    selectors({
        hasHealthIssue: [(s) => [s.unsnoozedCount], (unsnoozedCount: number): boolean => unsnoozedCount > 0],
        triggerBadgeContent: [
            (s) => [s.hasHealthIssue],
            (hasHealthIssue: boolean): string => (hasHealthIssue ? '!' : ''),
        ],
        triggerBadgeStatus: [
            (s) => [s.hasHealthIssue, s.criticalCount, s.warningCount],
            (hasHealthIssue: boolean, criticalCount: number, warningCount: number): HelpBadgeStatus => {
                if (!hasHealthIssue) {
                    return 'success'
                }
                if (criticalCount > 0) {
                    return 'danger'
                }
                if (warningCount > 0) {
                    return 'warning'
                }
                return 'success'
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        copyAccountOwnerEmail: () => {
            const { name, email } = values.accountOwner ?? {}
            if (!name || !email) {
                return
            }
            void copyToClipboard(email, 'email')
            actions.reportAccountOwnerClicked({ name, email })
        },
    })),
])
